import * as THREE from 'three';

const EYE_WHITE = new THREE.MeshBasicMaterial({ color: 0xfff3fd, toneMapped: false });
const PUPIL = new THREE.MeshBasicMaterial({ color: 0x120016 });
const SPARK = new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false });
const MOUTH = new THREE.MeshStandardMaterial({ color: 0x3a002c, roughness: 0.22, metalness: 0.5 });
const BLUSH = new THREE.MeshBasicMaterial({ color: 0xff5fa8, transparent: true, opacity: 0.52, depthWrite: false });
const CENTER = new THREE.MeshPhysicalMaterial({
  color: 0xfff0fb,
  metalness: 0.45,
  roughness: 0.15,
  clearcoat: 1,
  iridescence: 0.8,
  envMapIntensity: 1.5
});

const eyeWhiteGeo = new THREE.SphereGeometry(1, 18, 14);
const pupilGeo = new THREE.SphereGeometry(1, 14, 12);
const sparkGeo = new THREE.SphereGeometry(1, 10, 8);
const mouthGeo = new THREE.TorusGeometry(0.055, 0.013, 6, 16, Math.PI);
const blushGeo = new THREE.CircleGeometry(0.07, 16);
const footGeo = new THREE.SphereGeometry(0.1, 16, 12);
const petalGeo = new THREE.SphereGeometry(1, 20, 14);

function makeBlobGeometry() {
  const geometry = new THREE.SphereGeometry(0.5, 48, 34);
  const position = geometry.attributes.position;
  const vertex = new THREE.Vector3();
  for (let i = 0; i < position.count; i += 1) {
    vertex.fromBufferAttribute(position, i);
    const noise = 1 + 0.055 * Math.sin(vertex.x * 7.2 + 1.4) * Math.sin(vertex.y * 6.1 - 0.6) * Math.sin(vertex.z * 5.4 + 2.2);
    vertex.multiplyScalar(noise);
    position.setXYZ(i, vertex.x, vertex.y, vertex.z);
  }
  geometry.computeVertexNormals();
  return geometry;
}

function makeStarGeometry() {
  const shape = new THREE.Shape();
  const points = 10;
  for (let i = 0; i < points; i += 1) {
    const angle = (i / points) * Math.PI * 2 - Math.PI / 2;
    const radius = i % 2 === 0 ? 0.52 : 0.23;
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;
    if (i === 0) shape.moveTo(x, y);
    else shape.lineTo(x, y);
  }
  shape.closePath();
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: 0.16,
    bevelEnabled: true,
    bevelSegments: 3,
    bevelSize: 0.03,
    bevelThickness: 0.03,
    curveSegments: 2
  });
  geometry.center();
  return geometry;
}

const BLOB_GEO = makeBlobGeometry();
const STAR_GEO = makeStarGeometry();

function makeShadowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const context = canvas.getContext('2d');
  const gradient = context.createRadialGradient(64, 64, 2, 64, 64, 62);
  gradient.addColorStop(0, 'rgba(0,0,0,0.72)');
  gradient.addColorStop(0.5, 'rgba(0,0,0,0.34)');
  gradient.addColorStop(1, 'rgba(0,0,0,0)');
  context.fillStyle = gradient;
  context.fillRect(0, 0, 128, 128);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const SHADOW_TEXTURE = makeShadowTexture();
const SHADOW_MATERIAL = new THREE.MeshBasicMaterial({
  map: SHADOW_TEXTURE,
  transparent: true,
  depthWrite: false,
  opacity: 0.4
});
const SHADOW_GEO = new THREE.PlaneGeometry(1, 1);

const TYPE_WEIGHTS = [
  { type: 'blob', weight: 0.5 },
  { type: 'star', weight: 0.26 },
  { type: 'flower', weight: 0.24 }
];

function pickType() {
  const roll = Math.random();
  let sum = 0;
  for (const entry of TYPE_WEIGHTS) {
    sum += entry.weight;
    if (roll <= sum) return entry.type;
  }
  return 'blob';
}

function easeOutBack(value) {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  const x = value - 1;
  return 1 + c3 * x * x * x + c1 * x * x;
}

class Creature {
  constructor(type, color, home, scale, shadowRoot) {
    this.type = type;
    this.baseScale = scale;
    this.home = home.clone();
    this.phase = Math.random() * Math.PI * 2;
    this.speed = 0.55 + Math.random() * 0.55;
    this.drift = 0.09 + Math.random() * 0.16;
    this.spawn = 0;
    this.spawnDuration = 0.72 + Math.random() * 0.18;
    this.pulse = 0;
    this.blink = 2 + Math.random() * 4;
    this.blinking = 0;
    this.targetColor = new THREE.Color(color);
    this.spin = (Math.random() - 0.5) * 0.7;
    this.eyes = [];

    this.bodyMat = new THREE.MeshPhysicalMaterial({
      color: new THREE.Color(color),
      metalness: 0.22,
      roughness: 0.16,
      clearcoat: 1,
      clearcoatRoughness: 0.06,
      sheen: 0.9,
      sheenColor: new THREE.Color(0xffffff),
      sheenRoughness: 0.3,
      iridescence: 0.7,
      iridescenceIOR: 1.35,
      iridescenceThicknessRange: [100, 500],
      emissive: new THREE.Color(color),
      emissiveIntensity: 0.14,
      envMapIntensity: 1.45
    });

    this.group = new THREE.Group();
    this.group.position.copy(home);
    this.group.scale.setScalar(0.001);

    if (type === 'star') this.buildStar();
    else if (type === 'flower') this.buildFlower();
    else this.buildBlob();

    this.shadow = new THREE.Mesh(SHADOW_GEO, SHADOW_MATERIAL.clone());
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.position.set(home.x, 0.02, home.z);
    this.shadow.scale.setScalar(scale * 1.25);
    this.shadow.renderOrder = 2;
    shadowRoot.add(this.shadow);
  }

  addEyes(z, y, spread, scale = 1) {
    for (const side of [-1, 1]) {
      const eye = new THREE.Group();
      eye.position.set(side * spread, y, z);
      eye.rotation.y = side * 0.16;

      const white = new THREE.Mesh(eyeWhiteGeo, EYE_WHITE);
      white.scale.set(0.105 * scale, 0.13 * scale, 0.06 * scale);
      eye.add(white);

      const pupil = new THREE.Mesh(pupilGeo, PUPIL);
      pupil.position.set(0, 0.004, 0.055 * scale);
      pupil.scale.set(0.052 * scale, 0.075 * scale, 0.03 * scale);
      eye.add(pupil);

      const spark = new THREE.Mesh(sparkGeo, SPARK);
      spark.position.set(-side * 0.025 * scale, 0.03 * scale, 0.075 * scale);
      spark.scale.setScalar(0.024 * scale);
      eye.add(spark);

      this.group.add(eye);
      this.eyes.push(eye);
    }
  }

  addMouth(z, y, scale = 1) {
    const mouth = new THREE.Mesh(mouthGeo, MOUTH);
    mouth.position.set(0, y, z);
    mouth.rotation.z = Math.PI;
    mouth.scale.setScalar(scale);
    this.group.add(mouth);
  }

  addBlush(z, y, spread, scale = 1) {
    for (const side of [-1, 1]) {
      const blush = new THREE.Mesh(blushGeo, BLUSH);
      blush.position.set(side * spread, y, z);
      blush.rotation.y = side * 0.25;
      blush.scale.setScalar(scale);
      this.group.add(blush);
    }
  }

  buildBlob() {
    const body = new THREE.Mesh(BLOB_GEO, this.bodyMat);
    body.scale.set(1, 0.92, 1);
    this.group.add(body);
    this.body = body;

    this.addEyes(0.445, 0.075, 0.175, 1);
    this.addMouth(0.49, -0.12, 1);
    this.addBlush(0.43, -0.03, 0.3, 0.95);

    for (const side of [-1, 1]) {
      const foot = new THREE.Mesh(footGeo, this.bodyMat);
      foot.position.set(side * 0.19, -0.46, 0.12);
      foot.scale.set(1.1, 0.65, 1.2);
      this.group.add(foot);
    }

    if (Math.random() < 0.45) {
      for (const side of [-1, 1]) {
        const ear = new THREE.Mesh(new THREE.CapsuleGeometry(0.055, 0.18, 6, 10), this.bodyMat);
        ear.position.set(side * 0.17, 0.52, -0.02);
        ear.rotation.z = side * -0.22;
        this.group.add(ear);
      }
    }

    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.009, 0.012, 0.22, 6), this.bodyMat);
    antenna.position.set(0, 0.63, 0);
    this.group.add(antenna);
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.055, 14, 10), new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }));
    bulb.position.set(0, 0.76, 0);
    this.group.add(bulb);
  }

  buildStar() {
    const body = new THREE.Mesh(STAR_GEO, this.bodyMat);
    body.scale.setScalar(1.08);
    this.group.add(body);
    this.body = body;

    this.addEyes(0.1, 0.05, 0.14, 0.72);
    this.addMouth(0.105, -0.09, 0.7);
    this.addBlush(0.1, -0.01, 0.24, 0.62);
  }

  buildFlower() {
    const center = new THREE.Mesh(new THREE.SphereGeometry(0.29, 28, 20), CENTER);
    this.group.add(center);
    this.body = center;

    for (let i = 0; i < 8; i += 1) {
      const angle = (i / 8) * Math.PI * 2;
      const petal = new THREE.Mesh(petalGeo, this.bodyMat);
      petal.position.set(Math.cos(angle) * 0.37, Math.sin(angle) * 0.37, -0.03);
      petal.scale.set(0.17, 0.29, 0.075);
      petal.rotation.z = angle;
      this.group.add(petal);
    }

    this.addEyes(0.255, 0.06, 0.12, 0.68);
    this.addMouth(0.27, -0.055, 0.62);
    this.addBlush(0.245, 0.0, 0.21, 0.55);
  }

  setTargetColor(color) {
    this.targetColor.set(color);
  }

  update(dt, t, camera) {
    this.spawn = Math.min(1, this.spawn + dt / this.spawnDuration);
    this.pulse = Math.max(0, this.pulse - dt * 2.1);
    this.blink -= dt;

    if (this.blink <= 0) {
      this.blinking = 1;
      this.blink = 2.8 + Math.random() * 4.5;
    }
    if (this.blinking > 0) {
      this.blinking = Math.max(0, this.blinking - dt * 7);
    }

    const driftX = Math.sin(t * this.speed + this.phase) * this.drift;
    const driftZ = Math.cos(t * this.speed * 0.8 + this.phase * 1.4) * this.drift;
    this.group.position.set(
      this.home.x + driftX,
      this.home.y + Math.sin(t * 1.55 + this.phase) * 0.08,
      this.home.z + driftZ
    );

    const targetRotation = Math.atan2(camera.position.x - this.group.position.x, camera.position.z - this.group.position.z);
    this.group.rotation.y = targetRotation;
    if (this.type === 'star' || this.type === 'flower') {
      this.group.rotation.z = Math.sin(t * 0.6 + this.phase) * 0.14 + (this.type === 'star' ? t * this.spin : 0);
    } else {
      this.group.rotation.z = Math.sin(t * 0.8 + this.phase) * 0.03;
    }

    const spawnScale = easeOutBack(this.spawn);
    const pulseScale = 1 + Math.sin(this.pulse * Math.PI) * 0.22;
    this.group.scale.setScalar(this.baseScale * Math.max(0.001, spawnScale) * pulseScale);

    const colorBlend = 1 - Math.exp(-dt * 4.5);
    this.bodyMat.color.lerp(this.targetColor, colorBlend);
    this.bodyMat.emissive.copy(this.bodyMat.color).multiplyScalar(0.14);

    for (const eye of this.eyes) {
      eye.scale.y = 1 - this.blinking * 0.9;
    }

    const height = Math.max(0.2, this.group.position.y);
    this.shadow.position.set(this.group.position.x, 0.022, this.group.position.z);
    this.shadow.scale.setScalar(this.baseScale * (1.3 + height * 0.18));
    this.shadow.material.opacity = 0.34 * (1 - Math.min(0.65, height * 0.06));
  }

  dispose() {
    this.group.removeFromParent();
    this.shadow.removeFromParent();
    this.shadow.material.dispose();
    this.bodyMat.dispose();
  }
}

export class CreatureManager {
  constructor(scene, palette) {
    this.scene = scene;
    this.root = new THREE.Group();
    this.shadowRoot = new THREE.Group();
    this.root.name = 'creatures';
    scene.add(this.root, this.shadowRoot);
    this.creatures = [];
    this.palette = palette;
    this.max = 18;
  }

  setPalette(palette) {
    this.palette = palette;
  }

  spawnAt(x, y, z, options = {}) {
    if (this.creatures.length >= this.max) return null;
    const type = options.type || pickType();
    const colors = this.palette.creature;
    const color = options.color || colors[Math.floor(Math.random() * colors.length)];
    const scale = options.scale || 0.56 + Math.random() * 0.2;
    const home = new THREE.Vector3(
      x + (Math.random() - 0.5) * 0.5,
      y + (Math.random() - 0.5) * 0.12,
      z + (Math.random() - 0.5) * 0.5
    );
    const creature = new Creature(type, color, home, scale, this.shadowRoot);
    this.root.add(creature.group);
    this.creatures.push(creature);
    return creature;
  }

  createAt(point) {
    return this.spawnAt(point.x, 0.72 + Math.random() * 0.22, point.z);
  }

  seed() {
    const spots = [
      [2.35, 0.78, 0.7],
      [-2.55, 0.74, 0.2],
      [1.5, 0.7, -1.9],
      [-1.85, 0.82, -1.5],
      [3.35, 0.62, -0.55],
      [-3.25, 0.68, 1.25]
    ];
    const types = ['blob', 'flower', 'blob', 'star', 'blob', 'flower'];
    spots.forEach(([x, y, z], index) => {
      this.spawnAt(x, y, z, {
        type: types[index],
        scale: 0.58 + (index % 3) * 0.08,
        color: this.palette.creature[index % this.palette.creature.length]
      });
    });
  }

  destroyNear(point, radius) {
    const destroyed = [];
    for (let i = this.creatures.length - 1; i >= 0; i -= 1) {
      const creature = this.creatures[i];
      const dx = creature.group.position.x - point.x;
      const dz = creature.group.position.z - point.z;
      if (Math.hypot(dx, dz) <= radius) {
        destroyed.push({
          position: creature.group.position.clone(),
          color: creature.bodyMat.color.clone(),
          scale: creature.baseScale
        });
        creature.dispose();
        this.creatures.splice(i, 1);
      }
    }
    return destroyed;
  }

  change(palette) {
    this.setPalette(palette);
    const colors = palette.creature;
    this.creatures.forEach((creature, index) => {
      creature.setTargetColor(colors[(index + Math.floor(Math.random() * colors.length)) % colors.length]);
      creature.pulse = 1;
      creature.spin = (Math.random() - 0.5) * 1.2;
      creature.home.x += (Math.random() - 0.5) * 0.5;
      creature.home.z += (Math.random() - 0.5) * 0.5;
    });
  }

  reset() {
    for (const creature of this.creatures) creature.dispose();
    this.creatures.length = 0;
    this.seed();
  }

  update(dt, t, camera) {
    for (const creature of this.creatures) creature.update(dt, t, camera);
  }

  get count() {
    return this.creatures.length;
  }
}

import * as THREE from 'three';

const MAX_PARTICLES = 2600;
const MAX_SHARDS = 420;

function makeHeartTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const context = canvas.getContext('2d');
  context.translate(64, 68);
  context.scale(1.15, 1.15);
  context.beginPath();
  context.moveTo(0, 30);
  context.bezierCurveTo(-48, -10, -42, -52, -14, -52);
  context.bezierCurveTo(-4, -52, 0, -44, 0, -36);
  context.bezierCurveTo(0, -44, 4, -52, 14, -52);
  context.bezierCurveTo(42, -52, 48, -10, 0, 30);
  const gradient = context.createLinearGradient(-40, -50, 40, 30);
  gradient.addColorStop(0, '#ffffff');
  gradient.addColorStop(0.4, '#ffb4ec');
  gradient.addColorStop(1, '#ff2fa8');
  context.fillStyle = gradient;
  context.shadowColor = 'rgba(255, 95, 210, 0.9)';
  context.shadowBlur = 18;
  context.fill();
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

class ParticleField {
  constructor(scene) {
    this.positions = new Float32Array(MAX_PARTICLES * 3);
    this.colors = new Float32Array(MAX_PARTICLES * 3);
    this.sizes = new Float32Array(MAX_PARTICLES);
    this.alphas = new Float32Array(MAX_PARTICLES);
    this.velocities = new Float32Array(MAX_PARTICLES * 3);
    this.life = new Float32Array(MAX_PARTICLES);
    this.maxLife = new Float32Array(MAX_PARTICLES);
    this.gravity = new Float32Array(MAX_PARTICLES);
    this.drag = new Float32Array(MAX_PARTICLES);
    this.baseSize = new Float32Array(MAX_PARTICLES);
    this.cursor = 0;
    this.ambientTimer = 0;
    this.ambientColors = [new THREE.Color(0xffffff), new THREE.Color(0xff8ae8), new THREE.Color(0x7df9ff)];

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));

    this.material = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uPixelRatio: { value: 1 } },
      vertexShader: `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        uniform float uPixelRatio;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * uPixelRatio * (520.0 / max(0.2, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        precision highp float;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 p = gl_PointCoord - 0.5;
          float d = length(p);
          float core = smoothstep(0.5, 0.03, d);
          float cross = max(0.0, 1.0 - abs(p.x) * 16.0) * max(0.0, 1.0 - abs(p.y) * 2.2)
                      + max(0.0, 1.0 - abs(p.y) * 16.0) * max(0.0, 1.0 - abs(p.x) * 2.2);
          float alpha = core * 0.82 + cross * 0.38;
          if (alpha < 0.01) discard;
          gl_FragColor = vec4(vColor, alpha * vAlpha);
        }
      `
    });

    this.points = new THREE.Points(geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
    scene.add(this.points);
  }

  setPixelRatio(value) {
    this.material.uniforms.uPixelRatio.value = value;
  }

  setColors(colors) {
    this.ambientColors = colors;
  }

  spawnBurst(origin, colors, count = 100, options = {}) {
    const {
      speed = 2.6,
      spread = 1,
      life = 1.2,
      size = 0.16,
      gravity = -1.2,
      drag = 0.94,
      upBias = 0.25
    } = options;
    const palette = colors && colors.length ? colors : this.ambientColors;

    for (let n = 0; n < count; n += 1) {
      const index = this.cursor;
      this.cursor = (this.cursor + 1) % MAX_PARTICLES;
      const i3 = index * 3;
      const angle = Math.random() * Math.PI * 2;
      const horizontal = Math.random() * speed * spread;
      const vertical = (Math.random() - 0.5 + upBias) * speed;
      const color = palette[Math.floor(Math.random() * palette.length)];

      this.positions[i3] = origin.x + (Math.random() - 0.5) * 0.22;
      this.positions[i3 + 1] = origin.y + (Math.random() - 0.5) * 0.22;
      this.positions[i3 + 2] = origin.z + (Math.random() - 0.5) * 0.22;
      this.velocities[i3] = Math.cos(angle) * horizontal;
      this.velocities[i3 + 1] = vertical;
      this.velocities[i3 + 2] = Math.sin(angle) * horizontal;
      this.colors[i3] = color.r;
      this.colors[i3 + 1] = color.g;
      this.colors[i3 + 2] = color.b;
      this.sizes[index] = size * (0.55 + Math.random() * 0.9);
      this.baseSize[index] = this.sizes[index];
      this.life[index] = life * (0.7 + Math.random() * 0.7);
      this.maxLife[index] = this.life[index];
      this.alphas[index] = 1;
      this.gravity[index] = gravity;
      this.drag[index] = drag;
    }

    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.aColor.needsUpdate = true;
    this.points.geometry.attributes.aSize.needsUpdate = true;
    this.points.geometry.attributes.aAlpha.needsUpdate = true;
  }

  spawnAmbient(t) {
    const index = this.cursor;
    this.cursor = (this.cursor + 1) % MAX_PARTICLES;
    const i3 = index * 3;
    const angle = Math.random() * Math.PI * 2;
    const radius = 1.8 + Math.random() * 6.4;
    const color = this.ambientColors[Math.floor(Math.random() * this.ambientColors.length)];

    this.positions[i3] = Math.cos(angle) * radius;
    this.positions[i3 + 1] = 0.15 + Math.random() * 5.4;
    this.positions[i3 + 2] = Math.sin(angle) * radius * 0.72;
    this.velocities[i3] = (Math.random() - 0.5) * 0.08;
    this.velocities[i3 + 1] = 0.05 + Math.random() * 0.12;
    this.velocities[i3 + 2] = (Math.random() - 0.5) * 0.08;
    this.colors[i3] = color.r;
    this.colors[i3 + 1] = color.g;
    this.colors[i3 + 2] = color.b;
    this.sizes[index] = 0.025 + Math.random() * 0.05;
    this.baseSize[index] = this.sizes[index];
    this.life[index] = 3.5 + Math.random() * 3.5;
    this.maxLife[index] = this.life[index];
    this.alphas[index] = 0.75;
    this.gravity[index] = 0;
    this.drag[index] = 1;
  }

  update(dt) {
    this.ambientTimer += dt;
    if (this.ambientTimer > 0.06) {
      this.ambientTimer = 0;
      this.spawnAmbient();
    }

    for (let index = 0; index < MAX_PARTICLES; index += 1) {
      if (this.life[index] <= 0) continue;
      this.life[index] -= dt;
      const i3 = index * 3;

      if (this.life[index] <= 0) {
        this.alphas[index] = 0;
        continue;
      }

      const drag = Math.pow(this.drag[index], dt * 60);
      this.velocities[i3] *= drag;
      this.velocities[i3 + 1] = this.velocities[i3 + 1] * drag + this.gravity[index] * dt;
      this.velocities[i3 + 2] *= drag;

      this.positions[i3] += this.velocities[i3] * dt;
      this.positions[i3 + 1] += this.velocities[i3 + 1] * dt;
      this.positions[i3 + 2] += this.velocities[i3 + 2] * dt;

      if (this.positions[i3 + 1] < 0.04) {
        this.positions[i3 + 1] = 0.04;
        this.velocities[i3 + 1] *= -0.35;
      }

      const remaining = this.life[index] / this.maxLife[index];
      this.alphas[index] = Math.min(1, remaining * 3.2) * Math.min(1, (1 - remaining) * 8 + 0.2);
      this.sizes[index] = this.baseSize[index] * (0.55 + remaining * 0.7);
    }

    const attributes = this.points.geometry.attributes;
    attributes.position.needsUpdate = true;
    attributes.aSize.needsUpdate = true;
    attributes.aAlpha.needsUpdate = true;
  }
}

class Shockwaves {
  constructor(scene) {
    this.scene = scene;
    this.ringGeo = new THREE.RingGeometry(0.9, 1, 96);
    this.sphereGeo = new THREE.SphereGeometry(1, 24, 16);
    this.items = [];
  }

  ring(position, color, options = {}) {
    const { maxScale = 7, life = 0.9, opacity = 0.9, vertical = false, delay = 0 } = options;
    const material = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false
    });
    const mesh = new THREE.Mesh(this.ringGeo, material);
    if (vertical) {
      mesh.position.set(position.x, position.y + 1.1, position.z);
    } else {
      mesh.rotation.x = -Math.PI / 2;
      mesh.position.set(position.x, 0.035, position.z);
    }
    mesh.scale.setScalar(0.15);
    mesh.renderOrder = 3;
    this.scene.add(mesh);
    this.items.push({ mesh, age: -delay, life, maxScale, opacity, base: 0.15 });
  }

  sphere(position, color, options = {}) {
    const { maxScale = 5, life = 0.65, opacity = 0.55 } = options;
    const material = new THREE.MeshBasicMaterial({
      color,
      wireframe: true,
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false
    });
    const mesh = new THREE.Mesh(this.sphereGeo, material);
    mesh.position.copy(position);
    mesh.position.y += 1.0;
    mesh.scale.setScalar(0.25);
    mesh.renderOrder = 3;
    this.scene.add(mesh);
    this.items.push({ mesh, age: 0, life, maxScale, opacity, base: 0.25 });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i -= 1) {
      const item = this.items[i];
      item.age += dt;
      if (item.age < 0) {
        item.mesh.visible = false;
        continue;
      }
      item.mesh.visible = true;
      const progress = Math.min(1, item.age / item.life);
      const eased = 1 - Math.pow(1 - progress, 2.2);
      item.mesh.scale.setScalar(item.base + eased * item.maxScale);
      item.mesh.material.opacity = item.opacity * Math.pow(1 - progress, 1.7);
      if (progress >= 1) {
        item.mesh.removeFromParent();
        item.mesh.material.dispose();
        this.items.splice(i, 1);
      }
    }
  }
}

class Shards {
  constructor(scene) {
    this.scene = scene;
    this.dummy = new THREE.Object3D();
    this.items = [];
    this.cursor = 0;
    this.material = new THREE.MeshStandardMaterial({
      metalness: 0.65,
      roughness: 0.18,
      emissive: 0x160012,
      emissiveIntensity: 0.7
    });
    this.mesh = new THREE.InstancedMesh(new THREE.TetrahedronGeometry(0.09, 0), this.material, MAX_SHARDS);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 3;
    const color = new THREE.Color(0xffffff);
    for (let i = 0; i < MAX_SHARDS; i += 1) {
      this.dummy.scale.setScalar(0);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this.dummy.matrix);
      this.mesh.setColorAt(i, color);
    }
    scene.add(this.mesh);
  }

  spawn(position, color, count = 14, scale = 1) {
    for (let n = 0; n < count; n += 1) {
      const index = this.cursor;
      this.cursor = (this.cursor + 1) % MAX_SHARDS;
      const angle = Math.random() * Math.PI * 2;
      const speed = (1.2 + Math.random() * 3.8) * scale;
      this.items[index] = {
        position: new THREE.Vector3(position.x, position.y, position.z),
        velocity: new THREE.Vector3(Math.cos(angle) * speed, 1.5 + Math.random() * 4.2, Math.sin(angle) * speed),
        rotation: new THREE.Euler(Math.random() * 6, Math.random() * 6, Math.random() * 6),
        spin: new THREE.Vector3((Math.random() - 0.5) * 12, (Math.random() - 0.5) * 12, (Math.random() - 0.5) * 12),
        life: 1.1 + Math.random() * 0.8,
        maxLife: 1.9,
        size: (0.65 + Math.random() * 0.9) * scale,
        color: color.clone()
      };
      this.mesh.setColorAt(index, color);
    }
    this.mesh.instanceColor.needsUpdate = true;
  }

  update(dt) {
    let changed = false;
    for (let index = 0; index < MAX_SHARDS; index += 1) {
      const item = this.items[index];
      if (!item) continue;
      changed = true;
      item.life -= dt;
      if (item.life <= 0) {
        this.items[index] = null;
        this.dummy.position.set(0, -10, 0);
        this.dummy.scale.setScalar(0);
        this.dummy.updateMatrix();
        this.mesh.setMatrixAt(index, this.dummy.matrix);
        continue;
      }

      item.velocity.y -= 8.4 * dt;
      item.position.addScaledVector(item.velocity, dt);
      if (item.position.y < 0.05) {
        item.position.y = 0.05;
        item.velocity.y *= -0.38;
        item.velocity.x *= 0.82;
        item.velocity.z *= 0.82;
      }
      item.rotation.x += item.spin.x * dt;
      item.rotation.y += item.spin.y * dt;
      item.rotation.z += item.spin.z * dt;

      const fade = Math.min(1, item.life * 2.2);
      this.dummy.position.copy(item.position);
      this.dummy.rotation.copy(item.rotation);
      this.dummy.scale.setScalar(item.size * fade);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(index, this.dummy.matrix);
    }
    if (changed) this.mesh.instanceMatrix.needsUpdate = true;
  }
}

class HeartSprites {
  constructor(scene) {
    this.scene = scene;
    this.texture = makeHeartTexture();
    this.items = [];
  }

  spawn(position, colors, count = 8) {
    for (let i = 0; i < count; i += 1) {
      const color = colors[Math.floor(Math.random() * colors.length)];
      const material = new THREE.SpriteMaterial({
        map: this.texture,
        color,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        opacity: 0.95
      });
      const sprite = new THREE.Sprite(material);
      sprite.position.set(
        position.x + (Math.random() - 0.5) * 0.8,
        position.y + 0.2 + Math.random() * 0.4,
        position.z + (Math.random() - 0.5) * 0.8
      );
      const scale = 0.16 + Math.random() * 0.16;
      sprite.scale.setScalar(scale);
      sprite.renderOrder = 4;
      this.scene.add(sprite);
      this.items.push({
        sprite,
        velocity: new THREE.Vector3((Math.random() - 0.5) * 0.5, 0.7 + Math.random() * 0.9, (Math.random() - 0.5) * 0.5),
        life: 1.4 + Math.random() * 1.2,
        maxLife: 2.6,
        scale,
        spin: (Math.random() - 0.5) * 2.4
      });
    }
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i -= 1) {
      const item = this.items[i];
      item.life -= dt;
      item.velocity.y += 0.25 * dt;
      item.sprite.position.addScaledVector(item.velocity, dt);
      item.sprite.material.rotation += item.spin * dt;
      item.sprite.scale.setScalar(item.scale * (1 + (1 - item.life / item.maxLife) * 0.45));
      item.sprite.material.opacity = Math.max(0, Math.min(0.95, item.life * 2.2));
      if (item.life <= 0) {
        item.sprite.removeFromParent();
        item.sprite.material.dispose();
        this.items.splice(i, 1);
      }
    }
  }
}

class CursorRing {
  constructor(scene) {
    this.group = new THREE.Group();
    this.group.visible = false;
    this.material = new THREE.MeshBasicMaterial({
      color: 0xff5fd2,
      transparent: true,
      opacity: 0.85,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false
    });
    this.dotMaterial = this.material.clone();

    const ring = new THREE.Mesh(new THREE.RingGeometry(0.46, 0.5, 64), this.material);
    const dot = new THREE.Mesh(new THREE.CircleGeometry(0.055, 20), this.dotMaterial);
    const diamondGeo = new THREE.OctahedronGeometry(0.045, 0);
    this.group.add(ring, dot);
    for (let i = 0; i < 4; i += 1) {
      const angle = (i / 4) * Math.PI * 2;
      const diamond = new THREE.Mesh(diamondGeo, this.dotMaterial);
      diamond.position.set(Math.cos(angle) * 0.63, Math.sin(angle) * 0.63, 0);
      this.group.add(diamond);
    }
    this.group.rotation.x = -Math.PI / 2;
    this.group.position.y = 0.04;
    this.group.renderOrder = 3;
    scene.add(this.group);
  }

  setColor(color) {
    this.material.color.set(color);
    this.dotMaterial.color.set(color);
  }

  setPosition(point) {
    this.group.position.set(point.x, 0.04, point.z);
  }

  setVisible(value) {
    this.group.visible = value;
  }

  update(t) {
    const pulse = 1 + Math.sin(t * 3.2) * 0.055;
    this.group.scale.setScalar(pulse);
    this.material.opacity = 0.7 + Math.sin(t * 2.4) * 0.12;
  }
}

export class FX {
  constructor(scene, renderer) {
    this.particles = new ParticleField(scene);
    this.shockwaves = new Shockwaves(scene);
    this.shards = new Shards(scene);
    this.hearts = new HeartSprites(scene);
    this.cursor = new CursorRing(scene);
    this.palette = null;
    this.setPixelRatio(renderer.getPixelRatio());
  }

  setPixelRatio(value) {
    this.particles.setPixelRatio(value);
  }

  setPalette(palette) {
    this.palette = palette;
    this.particles.setColors([
      new THREE.Color(0xffffff),
      new THREE.Color(palette.accent),
      new THREE.Color(palette.orbB),
      ...palette.creature.map((color) => new THREE.Color(color))
    ]);
    this.cursor.setColor(palette.accent);
  }

  setCursorColor(color) {
    this.cursor.setColor(color);
  }

  update(dt, t) {
    this.particles.update(dt);
    this.shockwaves.update(dt);
    this.shards.update(dt);
    this.hearts.update(dt);
    this.cursor.update(t);
  }
}

export class DivineAudio {
  constructor() {
    this.context = null;
    this.master = null;
    this.filter = null;
    this.enabled = false;
    this.noiseBuffer = null;
  }

  build() {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return false;
    const context = new AudioContext();
    this.context = context;

    const master = context.createGain();
    master.gain.value = 0;
    master.connect(context.destination);
    this.master = master;

    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 760;
    filter.Q.value = 0.8;
    filter.connect(master);
    this.filter = filter;

    const pad = context.createGain();
    pad.gain.value = 0.13;
    pad.connect(filter);

    const voices = [110, 164.81, 220, 329.63];
    voices.forEach((frequency, index) => {
      const oscillator = context.createOscillator();
      oscillator.type = index % 2 === 0 ? 'triangle' : 'sawtooth';
      oscillator.frequency.value = frequency;
      oscillator.detune.value = (index - 1.5) * 7;
      const gain = context.createGain();
      gain.gain.value = 0.16 / (index + 1);
      oscillator.connect(gain).connect(pad);
      oscillator.start();
    });

    const lfo = context.createOscillator();
    lfo.type = 'sine';
    lfo.frequency.value = 0.07;
    const lfoGain = context.createGain();
    lfoGain.gain.value = 260;
    lfo.connect(lfoGain).connect(filter.frequency);
    lfo.start();

    const length = Math.floor(context.sampleRate * 0.45);
    const buffer = context.createBuffer(1, length, context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2.2);
    }
    this.noiseBuffer = buffer;
    return true;
  }

  async enable() {
    if (!this.context && !this.build()) return false;
    if (this.context.state === 'suspended') await this.context.resume();
    this.enabled = true;
    const now = this.context.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setValueAtTime(this.master.gain.value, now);
    this.master.gain.linearRampToValueAtTime(0.15, now + 0.8);
    return true;
  }

  disable() {
    if (!this.context) return;
    this.enabled = false;
    const now = this.context.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setValueAtTime(this.master.gain.value, now);
    this.master.gain.linearRampToValueAtTime(0, now + 0.4);
  }

  async toggle() {
    if (this.enabled) {
      this.disable();
      return false;
    }
    return this.enable();
  }

  ping(frequency, duration = 0.5, volume = 0.05, type = 'triangle', delay = 0) {
    if (!this.enabled || !this.context) return;
    const now = this.context.currentTime + delay;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(frequency, now);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(volume, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    oscillator.connect(gain).connect(this.master);
    oscillator.start(now);
    oscillator.stop(now + duration + 0.02);
  }

  noise(volume = 0.1, duration = 0.3) {
    if (!this.enabled || !this.context || !this.noiseBuffer) return;
    const now = this.context.currentTime;
    const source = this.context.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.context.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 900;
    filter.Q.value = 0.7;
    const gain = this.context.createGain();
    gain.gain.setValueAtTime(volume, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    source.connect(filter).connect(gain).connect(this.master);
    source.start(now);
    source.stop(now + duration + 0.02);
  }

  sweep(from, to, duration = 0.7, volume = 0.045) {
    if (!this.enabled || !this.context) return;
    const now = this.context.currentTime;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(from, now);
    oscillator.frequency.exponentialRampToValueAtTime(to, now + duration);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(volume, now + 0.04);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    oscillator.connect(gain).connect(this.master);
    oscillator.start(now);
    oscillator.stop(now + duration + 0.02);
  }

  cast(mode) {
    if (!this.enabled || !this.context) return;
    if (mode === 'create') {
      [523.25, 659.25, 783.99, 1046.5].forEach((frequency, index) => {
        this.ping(frequency, 0.55, 0.038, 'triangle', index * 0.055);
      });
      this.sweep(320, 980, 0.5, 0.025);
    } else if (mode === 'change') {
      this.sweep(180, 1200, 0.8, 0.04);
      [392, 493.88, 587.33].forEach((frequency, index) => {
        this.ping(frequency, 0.7, 0.03, 'sine', index * 0.04);
      });
      this.noise(0.035, 0.5);
    } else {
      this.noise(0.14, 0.42);
      this.sweep(160, 36, 0.55, 0.08);
      this.ping(72, 0.7, 0.06, 'sine', 0.02);
    }
  }
}

