162: function createEnvironmentMap(renderer) {
163:   const pmrem = new THREE.PMREMGenerator(renderer);
164:   const envScene = new THREE.Scene();
165:   envScene.background = new THREE.Color(0x160020);
166: 
167:   const dome = new THREE.Mesh(
168:     new THREE.SphereGeometry(70, 32, 20),
169:     new THREE.ShaderMaterial({
170:       side: THREE.BackSide,
171:       uniforms: {},
172:       vertexShader: `
173:         varying vec3 vDir;
174:         void main() {
175:           vDir = position;
176:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
177:         }
178:       `,
179:       fragmentShader: `
180:         varying vec3 vDir;
181:         void main() {
182:           vec3 d = normalize(vDir);
183:           float h = d.y * 0.5 + 0.5;
184:           vec3 top = vec3(0.16, 0.01, 0.24);
185:           vec3 mid = vec3(1.8, 0.22, 1.25);
186:           vec3 low = vec3(0.05, 0.45, 0.75);
187:           vec3 col = mix(low, mid, smoothstep(0.22, 0.52, h));
188:           col = mix(col, top, smoothstep(0.52, 0.94, h));
189:           gl_FragColor = vec4(col, 1.0);
190:         }
191:       `
192:     })
193:   );
194:   envScene.add(dome);
195: 
196:   const panel = (color, position, scale, rotation) => {
197:     const material = new THREE.MeshBasicMaterial({ color: new THREE.Color(...color), side: THREE.DoubleSide });
198:     const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), material);
199:     mesh.position.set(...position);
200:     mesh.scale.set(...scale);
201:     mesh.rotation.set(...rotation);
202:     envScene.add(mesh);
203:   };
204: 
205:   panel([3.4, 0.7, 2.6], [-16, 4, 2], [16, 22, 1], [0, Math.PI / 2, 0]);
206:   panel([0.5, 2.7, 3.4], [16, 3, 0], [16, 20, 1], [0, -Math.PI / 2, 0]);
207:   panel([2.8, 2.8, 3.2], [0, 18, -4], [24, 24, 1], [Math.PI / 2, 0, 0]);
208:   panel([2.2, 0.4, 1.5], [0, 3, -20], [18, 14, 1], [0, 0, 0]);
209:   panel([0.5, 1.4, 2.2], [0, -8, 8], [20, 20, 1], [-Math.PI / 2, 0, 0]);
210: 
211:   const glow = new THREE.Mesh(new THREE.SphereGeometry(3, 24, 16), new THREE.MeshBasicMaterial({ color: new THREE.Color(4, 3.6, 4) }));
212:   glow.position.set(0, 12, 4);
213:   envScene.add(glow);
214: 
215:   const target = pmrem.fromScene(envScene, 0.035, 0.1, 120);
216:   pmrem.dispose();
217:   dome.geometry.dispose();
218:   dome.material.dispose();
219:   envScene.traverse((object) => {
220:     if (object.isMesh && object !== dome) {
221:       object.geometry.dispose();
222:       object.material.dispose();
223:     }
224:   });
225:   return target.texture;
226: }
