228: function makeSky() {
229:   const uniforms = {
230:     uTop: { value: new THREE.Color(0x120024) },
231:     uMid: { value: new THREE.Color(0xff4fc8) },
232:     uBot: { value: new THREE.Color(0x2a0738) },
233:     uAccent: { value: new THREE.Color(0xff7ae0) },
234:     uTime: { value: 0 }
235:   };
236:   const material = new THREE.ShaderMaterial({
237:     side: THREE.BackSide,
238:     depthWrite: false,
239:     uniforms,
240:     vertexShader: `
241:       varying vec3 vDir;
242:       void main() {
243:         vDir = position;
244:         gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
245:       }
246:     `,
247:     fragmentShader: `
248:       precision highp float;
249:       varying vec3 vDir;
250:       uniform vec3 uTop;
251:       uniform vec3 uMid;
252:       uniform vec3 uBot;
253:       uniform vec3 uAccent;
254:       uniform float uTime;
255: 
256:       float hash(vec2 p) {
257:         p = fract(p * vec2(123.34, 456.21));
258:         p += dot(p, p + 45.32);
259:         return fract(p.x * p.y);
260:       }
261: 
262:       void main() {
263:         vec3 d = normalize(vDir);
264:         float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);
265:         vec3 col = mix(uBot, uMid, smoothstep(0.24, 0.55, h));
266:         col = mix(col, uTop, smoothstep(0.56, 1.0, h));
267: 
268:         vec3 sunDir = normalize(vec3(0.0, 0.12, -1.0));
269:         float sun = pow(max(dot(d, sunDir), 0.0), 6.0);
270:         col += uAccent * sun * 0.16;
271:         float core = pow(max(dot(d, sunDir), 0.0), 90.0);
272:         col += mix(uAccent, vec3(1.0, 0.82, 1.0), 0.18) * core * 0.38;
273: 
274:         float band = sin(d.x * 8.0 + uTime * 0.2 + sin(d.y * 5.0 - uTime * 0.14) * 2.2) * 0.5 + 0.5;
275:         col += uAccent * band * 0.035 * smoothstep(0.2, 0.72, h) * (1.0 - smoothstep(0.78, 1.0, h));
276: 
277:         float horizon = exp(-abs(d.y) * 22.0);
278:         col += uAccent * horizon * 0.08;
279: 
280:         vec2 uv = vec2(atan(d.z, d.x) * 0.1591549 + 0.5, asin(clamp(d.y, -1.0, 1.0)) * 0.3183099 + 0.5);
281:         vec2 starCell = floor(uv * vec2(900.0, 450.0));
282:         float rnd = hash(starCell);
283:         float star = smoothstep(0.9965, 1.0, rnd) * (0.4 + 0.6 * pow(max(0.0, sin(uTime * 1.7 + rnd * 35.0)), 4.0));
284:         col += mix(vec3(1.0), uAccent, 0.4) * star * 1.5;
285: 
286:         gl_FragColor = vec4(col, 1.0);
287:       }
288:     `
289:   });
290:   const mesh = new THREE.Mesh(new THREE.SphereGeometry(58, 48, 32), material);
291:   mesh.renderOrder = -10;
292:   return { mesh, uniforms };
293: }
