295: function makeFloor() {
296:   const uniforms = {
297:     uBase: { value: new THREE.Color(0x180225) },
298:     uLine: { value: new THREE.Color(0xff5fd2) },
299:     uGlow: { value: new THREE.Color(0xff8ae8) },
300:     uTime: { value: 0 }
301:   };
302:   const material = new THREE.ShaderMaterial({
303:     transparent: true,
304:     depthWrite: false,
305:     uniforms,
306:     vertexShader: `
307:       varying vec3 vWorld;
308:       void main() {
309:         vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
310:         gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
311:       }
312:     `,
313:     fragmentShader: `
314:       precision highp float;
315:       varying vec3 vWorld;
316:       uniform vec3 uBase;
317:       uniform vec3 uLine;
318:       uniform vec3 uGlow;
319:       uniform float uTime;
320: 
321:       void main() {
322:         vec2 p = vWorld.xz;
323:         float r = length(p);
324: 
325:         vec2 q = p * 0.72;
326:         vec2 g = abs(fract(q - 0.5) - 0.5);
327:         float line = (1.0 - smoothstep(0.0, 0.032, min(g.x, g.y)));
328: 
329:         vec2 q2 = p * 0.18;
330:         vec2 g2 = abs(fract(q2 - 0.5) - 0.5);
331:         float line2 = (1.0 - smoothstep(0.0, 0.012, min(g2.x, g2.y)));
332: 
333:         float checker = mod(floor(p.x * 0.72) + floor(p.y * 0.72), 2.0);
334:         vec3 col = uBase;
335:         col += uLine * (line * 0.8 + line2 * 0.4);
336:         col += uLine * checker * 0.032;
337: 
338:         float rings = sin(r * 3.2 - uTime * 1.25) * 0.5 + 0.5;
339:         col += uGlow * pow(rings, 20.0) * 0.36 * (1.0 - smoothstep(1.0, 9.0, r));
340:         col += uGlow * exp(-r * 0.6) * 0.3;
341: 
342:         float rim = (1.0 - smoothstep(0.0, 0.07, abs(r - 5.7)));
343:         col += uGlow * rim * 1.25;
344:         float inner = (1.0 - smoothstep(0.0, 0.045, abs(r - 2.1)));
345:         col += uGlow * inner * 0.5;
346: 
347:         float alpha = (1.0 - smoothstep(2.0, 10.5, r));
348:         gl_FragColor = vec4(col, alpha * 0.94);
349:       }
350:     `
351:   });
352:   const mesh = new THREE.Mesh(new THREE.PlaneGeometry(36, 36), material);
353:   mesh.rotation.x = -Math.PI / 2;
354:   mesh.position.y = 0;
355:   mesh.renderOrder = 1;
356:   return { mesh, uniforms };
357: }
