404: function buildGoddess(pearlMat, chromeMat, gownMat, hairMat, glowMat, darkMat, eyeIrisMat, crownMat, gemMat) {
405:   const group = new THREE.Group();
406:   group.name = 'goddess';
407: 
408:   // Gown -------------------------------------------------------------
409:   const gownProfile = [
410:     [0.0, 0.0], [1.34, 0.0], [1.44, 0.08], [1.32, 0.34],
411:     [1.08, 0.8], [0.9, 1.28], [0.76, 1.78], [0.64, 2.24],
412:     [0.56, 2.62], [0.58, 2.88], [0.5, 3.02]
413:   ].map(([x, y]) => new THREE.Vector2(x, y));
414:   const gownGeometry = new THREE.LatheGeometry(gownProfile, 128, 0, Math.PI * 2);
415:   const gownPositions = gownGeometry.attributes.position;
416:   for (let i = 0; i < gownPositions.count; i += 1) {
417:     let x = gownPositions.getX(i);
418:     let y = gownPositions.getY(i);
419:     let z = gownPositions.getZ(i);
420:     const angle = Math.atan2(z, x);
421:     const pleat = 1 + 0.026 * Math.cos(angle * 18) + 0.014 * Math.sin(angle * 7 + y * 1.2);
422:     const hemFlare = 1 + 0.05 * Math.sin(angle * 6) * Math.max(0, 1 - y / 0.65);
423:     x *= pleat * hemFlare;
424:     z *= pleat * hemFlare;
425:     gownPositions.setXYZ(i, x, y, z);
426:   }
427:   gownGeometry.computeVertexNormals();
428:   const gown = new THREE.Mesh(gownGeometry, gownMat);
429:   gown.castShadow = false;
