432:   gownMat.onBeforeCompile = (shader) => {
433:     shader.uniforms.uTime = { value: 0 };
434:     shader.vertexShader = shader.vertexShader
435:       .replace('#include <common>', '#include <common>\nuniform float uTime;')
436:       .replace(
437:         '#include <begin_vertex>',
438:         `#include <begin_vertex>
439:         float swayHeight = smoothstep(0.0, 2.35, position.y);
440:         float swayAngle = atan(position.z, position.x);
441:         float sway = sin(uTime * 1.15 + position.y * 1.7 + swayAngle * 2.0) * 0.034 * (1.0 - swayHeight);
442:         transformed.x += sway;
443:         transformed.z += sway * 0.55;`
444:       );
