446:   };
447: 
448:   // Torso ------------------------------------------------------------
449:   const torsoProfile = [
450:     [0.0, 2.94], [0.48, 2.96], [0.55, 3.12], [0.59, 3.32],
451:     [0.55, 3.5], [0.46, 3.64], [0.31, 3.74], [0.15, 3.79]
