453:   const torsoGeometry = new THREE.LatheGeometry(torsoProfile, 64);
454:   torsoGeometry.scale(1, 1, 0.78);
455:   const torso = new THREE.Mesh(torsoGeometry, pearlMat);
456:   group.add(torso);
