466:   const bodiceProfile = [
467:     [0.0, 2.97], [0.51, 2.99], [0.57, 3.12], [0.6, 3.3],
468:     [0.56, 3.44], [0.46, 3.55], [0.31, 3.6]
469:   ].map(([x, y]) => new THREE.Vector2(x, y));
470:   const bodiceGeometry = new THREE.LatheGeometry(bodiceProfile, 72);
471:   bodiceGeometry.scale(1, 1, 0.8);
472:   const bodice = new THREE.Mesh(bodiceGeometry, gownMat);
473:   group.add(bodice);
