479:   group.add(bodiceTrim);
480: 
481:   // Neck + head ------------------------------------------------------
482:   const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.12, 0.26, 20), pearlMat);
483:   neck.position.set(0, 3.87, 0);
484:   group.add(neck);
485: 
486:   const head = new THREE.Mesh(new THREE.SphereGeometry(0.42, 48, 36), pearlMat);
487:   head.position.set(0, 4.31, 0.01);
488:   head.scale.set(0.9, 1.04, 0.95);
