496:   const lip = new THREE.Mesh(new THREE.TorusGeometry(0.058, 0.011, 8, 20, Math.PI), darkMat);
497:   lip.position.set(0, 4.15, 0.4);
498:   lip.rotation.z = Math.PI;
499:   lip.scale.set(1, 0.65, 1);
500:   group.add(lip);
501: 
502:   const eyeWhiteMat = new THREE.MeshBasicMaterial({ color: 0xffeafb, toneMapped: false });
503:   const pupilMat = new THREE.MeshBasicMaterial({ color: 0x0a0012 });
504:   const eyeWhiteGeo = new THREE.SphereGeometry(1, 18, 14);
505:   const irisGeo = new THREE.SphereGeometry(1, 16, 12);
506:   const highlightMat = new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false });
507: 
508:   for (const side of [-1, 1]) {
509:     const eye = new THREE.Group();
510:     eye.position.set(side * 0.145, 4.375, 0.352);
