527:     const spark = new THREE.Mesh(irisGeo, highlightMat);
528:     spark.position.set(-side * 0.018, 0.018, 0.064);
529:     spark.scale.setScalar(0.012);
530:     eye.add(spark);
531: 
532:     group.add(eye);
533: 
534:     const browCurve = new THREE.CatmullRomCurve3([
535:       new THREE.Vector3(side * 0.06, 4.48, 0.385),
536:       new THREE.Vector3(side * 0.15, 4.505, 0.39),
537:       new THREE.Vector3(side * 0.235, 4.48, 0.365)
538:     ]);
539:     const brow = new THREE.Mesh(new THREE.TubeGeometry(browCurve, 16, 0.011, 5, false), darkMat);
540:     group.add(brow);
541: 
542:     const cheekGem = new THREE.Mesh(new THREE.OctahedronGeometry(0.018, 0), gemMat);
543:     cheekGem.position.set(side * 0.27, 4.29, 0.31);
