547:   // Hair -------------------------------------------------------------
548:   const hairCap = new THREE.Mesh(new THREE.SphereGeometry(0.455, 40, 28), hairMat);
549:   hairCap.position.set(0, 4.35, -0.1);
550:   hairCap.scale.set(1.03, 1.06, 1.0);
551:   group.add(hairCap);
