560:   const strandCount = 15;
561:   for (let i = 0; i < strandCount; i += 1) {
562:     const t = i / (strandCount - 1);
563:     const angle = 0.62 + t * (Math.PI * 2 - 1.24);
564:     const wave = Math.sin(t * 13.0) * 0.08;
565:     const radius = 0.31 + 0.12 * Math.sin(t * 7.0);
566:     const start = new THREE.Vector3(
567:       Math.sin(angle) * radius,
568:       4.62 + Math.sin(t * 9.0) * 0.05,
569:       Math.cos(angle) * radius - 0.06
570:     );
571:     const mid = new THREE.Vector3(
572:       Math.sin(angle) * (0.52 + wave),
