580:     );
581:     const end = new THREE.Vector3(
582:       Math.sin(angle) * (0.7 + wave * 1.8),
583:       2.34 + Math.sin(t * 11.0) * 0.24,
584:       Math.cos(angle) * (0.62 + wave * 1.8) - 0.14
585:     );
586:     const curve = new THREE.CatmullRomCurve3([start, mid, lower, end]);
587:     const radiusHair = 0.044 + Math.sin(t * 5.0) * 0.012;
588:     const strand = new THREE.Mesh(new THREE.TubeGeometry(curve, 36, radiusHair, 6, false), hairMat);
589:     group.add(strand);
