591: 
592:   const bangCurves = [
593:     [[-0.33, 4.6, 0.19], [-0.18, 4.55, 0.34], [-0.04, 4.6, 0.37]],
594:     [[0.33, 4.6, 0.19], [0.18, 4.55, 0.34], [0.04, 4.6, 0.37]]
595:   ];
596:   for (const points of bangCurves) {
597:     const curve = new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(...p)));
598:     group.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 20, 0.052, 6, false), hairMat));
599:   }
600: 
601:   for (let i = 0; i < 7; i += 1) {
