281:       const eased = 1 - Math.pow(1 - progress, 2.2);
282:       item.mesh.scale.setScalar(item.base + eased * item.maxScale);
283:       item.mesh.material.opacity = item.opacity * Math.pow(1 - progress, 1.7);
284:       if (progress >= 1) {
285:         item.mesh.removeFromParent();
286:         item.mesh.material.dispose();
287:         this.items.splice(i, 1);
288:       }
289:     }
290:   }
291: }
