293: class Shards {
294:   constructor(scene) {
295:     this.scene = scene;
296:     this.dummy = new THREE.Object3D();
297:     this.items = [];
298:     this.cursor = 0;
299:     this.material = new THREE.MeshStandardMaterial({
300:       metalness: 0.65,
301:       roughness: 0.18,
302:       emissive: 0x160012,
303:       emissiveIntensity: 0.7
304:     });
305:     this.mesh = new THREE.InstancedMesh(new THREE.TetrahedronGeometry(0.09, 0), this.material, MAX_SHARDS);
306:     this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
307:     this.mesh.frustumCulled = false;
308:     this.mesh.renderOrder = 3;
309:     const color = new THREE.Color(0xffffff);
310:     for (let i = 0; i < MAX_SHARDS; i += 1) {
311:       this.dummy.scale.setScalar(0);
312:       this.dummy.updateMatrix();
313:       this.mesh.setMatrixAt(i, this.dummy.matrix);
314:       this.mesh.setColorAt(i, color);
315:     }
316:     scene.add(this.mesh);
317:   }
318: 
319:   spawn(position, color, count = 14, scale = 1) {
320:     for (let n = 0; n < count; n += 1) {
321:       const index = this.cursor;
322:       this.cursor = (this.cursor + 1) % MAX_SHARDS;
323:       const angle = Math.random() * Math.PI * 2;
324:       const speed = (1.2 + Math.random() * 3.8) * scale;
325:       this.items[index] = {
326:         position: new THREE.Vector3(position.x, position.y, position.z),
327:         velocity: new THREE.Vector3(Math.cos(angle) * speed, 1.5 + Math.random() * 4.2, Math.sin(angle) * speed),
328:         rotation: new THREE.Euler(Math.random() * 6, Math.random() * 6, Math.random() * 6),
329:         spin: new THREE.Vector3((Math.random() - 0.5) * 12, (Math.random() - 0.5) * 12, (Math.random() - 0.5) * 12),
330:         life: 1.1 + Math.random() * 0.8,
331:         maxLife: 1.9,
332:         size: (0.65 + Math.random() * 0.9) * scale,
333:         color: color.clone()
334:       };
335:       this.mesh.setColorAt(index, color);
336:     }
337:     this.mesh.instanceColor.needsUpdate = true;
338:   }
339: 
340:   update(dt) {
341:     let changed = false;
342:     for (let index = 0; index < MAX_SHARDS; index += 1) {
343:       const item = this.items[index];
344:       if (!item) continue;
345:       changed = true;
346:       item.life -= dt;
347:       if (item.life <= 0) {
348:         this.items[index] = null;
349:         this.dummy.position.set(0, -10, 0);
350:         this.dummy.scale.setScalar(0);
351:         this.dummy.updateMatrix();
352:         this.mesh.setMatrixAt(index, this.dummy.matrix);
353:         continue;
354:       }
355: 
356:       item.velocity.y -= 8.4 * dt;
357:       item.position.addScaledVector(item.velocity, dt);
358:       if (item.position.y < 0.05) {
359:         item.position.y = 0.05;
360:         item.velocity.y *= -0.38;
361:         item.velocity.x *= 0.82;
362:         item.velocity.z *= 0.82;
363:       }
364:       item.rotation.x += item.spin.x * dt;
365:       item.rotation.y += item.spin.y * dt;
366:       item.rotation.z += item.spin.z * dt;
367: 
368:       const fade = Math.min(1, item.life * 2.2);
369:       this.dummy.position.copy(item.position);
370:       this.dummy.rotation.copy(item.rotation);
371:       this.dummy.scale.setScalar(item.size * fade);
372:       this.dummy.updateMatrix();
373:       this.mesh.setMatrixAt(index, this.dummy.matrix);
374:     }
375:     if (changed) this.mesh.instanceMatrix.needsUpdate = true;
376:   }
377: }
