import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'))
process.env.DISPLAY = ':' + readFileSync(runtime + '/display','utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const errors = []
async function open(viewport) {
  const page = await browser.newPage({ viewport })
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()) })
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.stack))
  page.on('requestfailed', r => errors.push('REQFAIL ' + r.url() + ' ' + r.failure()?.errorText))
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(2600)
  return page
}
const desktop = await open({ width: 1440, height: 900 })
await desktop.screenshot({ path: '/tmp/opencode/tune-desktop.png' })
// Palettes at rest
for (let i = 1; i < 4; i++) {
  await desktop.evaluate((index) => {
    const omni = window.__OMNI__
    // force palette by repeated cast calls with no FX after applying via private world set
    omni.world.setPalette([
      {name:'GENESIS'}, // dummy not used
    ][0])
  }, i).catch(() => {})
}
await desktop.evaluate(() => window.__OMNI__.setMode('change'))
for (let i = 1; i < 4; i++) {
  await desktop.mouse.click(700, 650)
  await desktop.waitForTimeout(2200)
  await desktop.screenshot({ path: `/tmp/opencode/tune-palette-${i}.png` })
}
await desktop.close()
const mobile = await open({ width: 390, height: 844 })
await mobile.screenshot({ path: '/tmp/opencode/tune-mobile.png' })
await mobile.close()
const landscape = await open({ width: 844, height: 390 })
await landscape.screenshot({ path: '/tmp/opencode/tune-landscape.png' })
await landscape.close()
console.log('ERRORS', errors.length ? errors.join('\n') : 'none')
await browser.close()

