import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'))
process.env.DISPLAY = ':' + readFileSync(runtime + '/display','utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const errors = []
async function open(viewport) {
  const page = await browser.newPage({ viewport })
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()) })
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.stack))
  page.on('requestfailed', r => errors.push('REQFAIL ' + r.url() + ' ' + r.failure()?.errorText))
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(2600)
  return page
}
const desktop = await open({ width: 1440, height: 900 })
await desktop.screenshot({ path: '/tmp/opencode/tune2-desktop.png' })
for (let i = 1; i < 4; i++) {
  await desktop.evaluate((index) => window.__OMNI__.applyPalette(index, true), i)
  await desktop.waitForTimeout(1200)
  await desktop.screenshot({ path: `/tmp/opencode/tune2-palette-${i}.png` })
}
await desktop.evaluate(() => window.__OMNI__.applyPalette(0, true))
await desktop.waitForTimeout(600)
// Create settled state
await desktop.evaluate(() => {
  window.__OMNI__.setMode('create')
  window.__OMNI__.cast('create', { x: 2.4, y: 0, z: 2.2 })
})
await desktop.waitForTimeout(2200)
await desktop.screenshot({ path: '/tmp/opencode/tune2-create.png' })
// Destroy settled state
await desktop.evaluate(() => {
  window.__OMNI__.setMode('destroy')
  window.__OMNI__.cast('destroy', { x: 2.4, y: 0, z: 2.2 })
})
await desktop.waitForTimeout(2200)
await desktop.screenshot({ path: '/tmp/opencode/tune2-destroy.png' })
await desktop.close()
const mobile = await open({ width: 390, height: 844 })
await mobile.screenshot({ path: '/tmp/opencode/tune2-mobile.png' })
await mobile.close()
const landscape = await open({ width: 844, height: 390 })
await landscape.screenshot({ path: '/tmp/opencode/tune2-landscape.png' })
await landscape.close()
console.log('ERRORS', errors.length ? errors.join('\n') : 'none')
await browser.close()

