import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'))
process.env.DISPLAY = ':' + readFileSync(runtime + '/display','utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
for (const [w, h, name] of [[320, 568, 'small'], [768, 1024, 'tablet'], [1024, 768, 'desktop-small']]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(2000)
  const layout = await page.evaluate(() => {
    const rect = (sel) => { const r = document.querySelector(sel).getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) } }
    return {
      viewport: [innerWidth, innerHeight],
      overflowX: document.documentElement.scrollWidth > innerWidth,
      overflowY: document.documentElement.scrollHeight > innerHeight,
      brand: rect('.brand'), actions: rect('.top-actions'), dock: rect('.dock'), hint: rect('#hint'), top: rect('.top'),
      powerLabels: [...document.querySelectorAll('.power .label')].map(e => e.textContent),
      body: document.body.className
    }
  })
  console.log(name, JSON.stringify(layout, null, 2), 'errors', errors)
  await page.screenshot({ path: `/tmp/opencode/layout-${name}.png` })
  await page.close()
}
await browser.close()
